UIConfettiEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,100);this.particleClass=UIConfettiParticle;this.makeParticles();this.minParticleSpeed.setTo(UIConstants.CONFETTI_MIN_X_SPEED,UIConstants.CONFETTI_MIN_Y_SPEED);this.maxParticleSpeed.setTo(UIConstants.CONFETTI_MAX_X_SPEED,UIConstants.CONFETTI_MAX_Y_SPEED);this.particleDrag.setTo(UIConstants.CONFETTI_DRAG,UIConstants.CONFETTI_DRAG);this.setAlpha(0.6,0.8);this.setRotation(-120,120);this.minParticleScale=0.5;this.maxParticleScale=1.0;this.gravity=UIConstants.CONFETTI_GRAVITY;this.kill();this.visible=false;};UIConfettiEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIConfettiEmitter.prototype.constructor=UIConfettiEmitter;UIConfettiEmitter.prototype.update=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UIConfettiEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIConfettiEmitter.prototype.spawn=function(x,y){this.revive();this.visible=true;this.x=x;this.y=y;this.explode(6500,100);};UIConfettiEmitter.prototype.remove=function(){this.on=false;};UIConfettiEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};